def _inter(a, b, common):
    c = build(common)
    def attach(h):
        if h is None:
            return c
        cur = h
        while cur.next:
            cur = cur.next
        cur.next = c
        return h
    return get_intersection(attach(build(a)), attach(build(b))) is c

